    // ThreadLocal 状态 — 对应 C++ thread_local
    private static final ThreadLocal<byte[]> fileKeyBytesTL = ThreadLocal.withInitial(() -> new byte[16 * 17]);
    private static final ThreadLocal<byte[]> maskBytesTL      = ThreadLocal.withInitial(() -> new byte[PRE_COMPUTED.length]);

    public static void init(byte[] ownKeyBytes) {
        byte[] fileKeyBytes = fileKeyBytesTL.get();
        byte[] maskBytes    = maskBytesTL.get();

        int n = Math.min(17, ownKeyBytes.length);
        System.arraycopy(ownKeyBytes, 0, fileKeyBytes, 0, n);
        for (int i = 1; i < 16; i++) System.arraycopy(fileKeyBytes, 0, fileKeyBytes, i * 17, 17);

        System.arraycopy(PRE_COMPUTED, 0, maskBytes, 0, PRE_COMPUTED.length);

        for (int i = 0; i < MASK_V2.length; i++) fileKeyBytes[i] ^= MASK_V2[i];
    }

    private static void genMask(int startPos) {
        byte[] maskBytes = maskBytesTL.get();
        byte[][] chunk = new byte[16][16];

        for (int pos = 0; pos < PRE_COMPUTED.length * 16; pos += 16 * 16 * 16) {
            int i = startPos + pos;
            i >>= 4;
            int chunkPreTablePos = i % PRE_COMPUTED.length;
            for (int k = 0; k < 16; ++k)
                System.arraycopy(PRE_COMPUTED, chunkPreTablePos + k * 16, chunk[k], 0, 16);

            i >>= 8;
            // startPos > 69632 才能这么用
            do {
                byte xorData = PRE_COMPUTED[i % PRE_COMPUTED.length];
                for (int k = 0; k < 16; ++k) {
                    byte[] ck = chunk[k];
                    for (int b = 0; b < 16; b++) ck[b] ^= xorData;
                }
                i >>= 8;
            } while (i >= 0x11);

            int storePos = pos >> 4;
            for (int k = 0; k < 16; ++k)
                System.arraycopy(chunk[k], 0, maskBytes, storePos + k * 16, 16);
        }
    }

    public static int decrypt(byte[] cipherDataBytes, int offset, int bytesRead) {
        byte[] fileKeyBytes = fileKeyBytesTL.get();
        byte[] maskBytes    = maskBytesTL.get();

        int i = offset;
        int j = 0;
        int genMaskCounter = offset % 69632;
        int fileKeyCounter = offset % 272;
        int maskBytesIndexCounter = (offset >> 4) % 4352;

        // 防止 buffer 在位置恰好为 69632 字节整数倍切换数据时，下方 if 函数未生成 mask
        if (genMaskCounter == 0) genMask(i);

        // SIMD: 每次处理 16 字节
        for (; j + 16 <= bytesRead; i += 16, j += 16) {
            // 简化取模运算
            if (genMaskCounter == 69632) { genMask(i); genMaskCounter = 0; }
            if (fileKeyCounter == 272) fileKeyCounter = 0;
            if (j > 0 && (i & 15) == 0) {
                maskBytesIndexCounter++;
                if (maskBytesIndexCounter == 4352) maskBytesIndexCounter = 0;
            }

            ByteVector vCipher = ByteVector.fromArray(SPECIES, cipherDataBytes, j);
            ByteVector vMed8   = ByteVector.fromArray(SPECIES, fileKeyBytes, fileKeyCounter);
            ByteVector vMsk8   = ByteVector.broadcast(SPECIES, maskBytes[maskBytesIndexCounter]);
            vMed8 = vMed8.lanewise(VectorOperators.XOR, vCipher);
            vMed8 = vMed8.lanewise(VectorOperators.XOR, vMsk8);
            vMsk8 = vMed8.lanewise(VectorOperators.LSHL, 4);
            vMsk8 = vMed8.lanewise(VectorOperators.XOR, vMsk8);
            // vMsk8 已为最终结果
            vMsk8.intoArray(cipherDataBytes, j);

            genMaskCounter += 16;
            fileKeyCounter += 16;
        }

        // 标量尾部
        for (; j < bytesRead; ++i, ++j) {
            if (genMaskCounter == 69632) { genMask(i); genMaskCounter = 0; }
            if (fileKeyCounter == 272) fileKeyCounter = 0;
            if (j > 0 && (i & 15) == 0) {
                maskBytesIndexCounter++;
                if (maskBytesIndexCounter == 4352) maskBytesIndexCounter = 0;
            }

            int combined = (fileKeyBytes[fileKeyCounter] & 0xFF)
                         ^ (cipherDataBytes[j] & 0xFF)
                         ^ (maskBytes[maskBytesIndexCounter] & 0xFF);
            cipherDataBytes[j] = (byte) (combined ^ (combined << 4));

            genMaskCounter++;
            fileKeyCounter++;
        }

        return i;
    }
